import unittest
from decimal import Decimal

from billing import invoice_amount


class InvoiceAmountTests(unittest.TestCase):
    def test_parses_decimal_string_without_float_rounding(self):
        self.assertEqual(invoice_amount("12.34"), Decimal("12.34"))

    def test_strips_surrounding_whitespace(self):
        self.assertEqual(invoice_amount(" 0.5 "), Decimal("0.5"))

    def test_rejects_non_string_and_invalid_amounts(self):
        with self.assertRaises(TypeError):
            invoice_amount(Decimal("1.00"))

        for value in ("", "-1.00", "+1.00", "1.234", "1e2", "$1.00", "1,000.00"):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    invoice_amount(value)


if __name__ == "__main__":
    unittest.main()
